@startuml

class Scene {
  +code : string
  +description : string
}

class Setup {
  +code : string
  +description : string
}

class Take {
  +number : int
  +film_meters : float
  +reel_code : string
}

class Internal extends Scene {}

class External extends Scene {}

class Location {
  +code : string
  +address : string
  +description : string
}

Scene "1" -- "1..*" Setup : filmed_from
Setup "1" -- "1..*" Take : has

External "0..*" -- "1" Location : located

@enduml

